import urllib.request
import re, json

folder_ids = {
    'ATOM': '1PCRf6iItL-8ZAi3p9zNvWg8bOAK3j_P7',
    'AGA': '1UFfNuH81fiT7puLGWYtGiPo3OWQ9RkUq',
    '痩身': '1gjmbBhgFzBRjEv4PANwc703MP4obUsix'
}

for name, fid in folder_ids.items():
    url = f'https://drive.google.com/drive/folders/{fid}'
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'})
    with urllib.request.urlopen(req) as resp:
        html = resp.read().decode('utf-8', errors='ignore')

    print(f'=== Folder: {name} ===')
    # scriptタグの中にあるJSON配列構造から、ファイル名（文字列）と更新日時/作成日時のペアを探す
    # ds:4 のコールバックデータ構造をパースしてみる
    match = re.search(r'AF_initDataCallback\({key: \'ds:4\'.*?data:(\[.*?\])\}\);', html, re.DOTALL)
    if match:
        try:
            data = json.loads(match.group(1))
            # 再帰的にリストを探索し、ファイル名（例: .mp4 や 2025年9月 などを含む要素）を見つける
            def find_files(node):
                if isinstance(node, list):
                    # Googleドライブのファイルエントリは通常、特定の長さのリスト（ID、名前、MIMEタイプなどを含む）
                    if len(node) > 2 and isinstance(node[1], str) and ('.' in node[1] or 'ZOOM' in node[1] or '録画' in node[1]):
                        print('    File entry:', node[1], node[2] if len(node) > 2 else '')
                    for child in node:
                        find_files(child)
                elif isinstance(node, dict):
                    for v in node.values():
                        find_files(v)
            find_files(data)
        except Exception as e:
            print('    Parse exception:', e)
